with flattened_attrs as (select id, status_code, coalesce(context['region'], 'none') as region_or_default, context['version'] as version, context['region'] as region, cast((status_code & 8) != 0 as int) as has_fault, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier as tier from app_logs where status_code between 267 and 289) select tier, avg(status_code) filter (where tier = 'gold') as gold_avg_status_code, count(*) as cnt, count(*) as row_count from flattened_attrs group by tier having avg(status_code) filter (where tier = 'gold') >= 0 order by tier desc;
